<script setup>
import { ref, nextTick } from 'vue'
import ExperimentEvidence from './ExperimentEvidence.vue'
const props=defineProps({ label:String, context:String, boundary:String, kinds:{type:Array,default:()=>[]} })
const names={coverage:'E3.8 预算验证',early:'E3.5 局部保真',noise:'冻结策略复跑',router:'旧状态路由',cifar:'历史 CIFAR 机制试验'}
const open=ref(false),selected=ref(props.kinds[0]),trigger=ref(null),dialog=ref(null)
async function show(){open.value=true;await nextTick();dialog.value?.focus()}
function close(){open.value=false;trigger.value?.focus()}
function trap(e){if(e.key!=='Tab')return;const nodes=dialog.value?.querySelectorAll('button,select,a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.target===dialog.value||(!e.shiftKey&&e.target===last)||(e.shiftKey&&e.target===first)){e.preventDefault();(e.shiftKey?last:first).focus()}}
</script>
<template><span class="plan-evidence-control" @click.stop @keydown.stop><button ref="trigger" class="evidence-trigger" type="button" aria-haspopup="dialog" :aria-expanded="open" @click="show">{{label}}</button><div v-if="open" class="evidence-shade" @click.self="close"><section ref="dialog" role="dialog" aria-modal="true" :aria-label="context" tabindex="-1" class="evidence-dialog" @keydown.esc.prevent.stop="close" @keydown="trap"><header><b>{{context}}</b><button type="button" @click="close" aria-label="关闭实验依据">关闭 ×</button></header><p class="evidence-boundary">{{boundary}}</p><nav aria-label="对应的先行实验"><button v-for="kind in kinds" :key="kind" type="button" :aria-pressed="selected===kind" @click="selected=kind">{{names[kind]}}</button></nav><div class="evidence-body" :key="selected"><ExperimentEvidence :kind="selected" /></div></section></div></span></template>
<style scoped>.plan-evidence-control{display:inline-flex;line-height:1.4}.evidence-trigger{font:inherit;font-size:17px;border:1px solid #b9cdd0;color:#416f83;background:#eaf0ee;border-radius:5px;padding:4px 9px;cursor:pointer}.evidence-shade{position:absolute;inset:12px;z-index:95;padding:12px;background:#20394380;border-radius:12px;display:flex}.evidence-dialog{display:flex;flex-direction:column;width:100%;min-height:0;padding:15px 20px;background:#f8f6f0;border:1px solid #cbd7d4;border-radius:10px;gap:10px;color:#20333b;outline:none}.evidence-dialog header{display:flex;justify-content:space-between;align-items:center;gap:20px}.evidence-dialog header b{font-size:25px;font-weight:600}.evidence-dialog button{font:inherit;font-size:18px;padding:5px 10px;border:1px solid #b7ccd0;border-radius:5px;background:#edf2ef;color:#416f83;cursor:pointer}.evidence-dialog nav{display:flex;gap:8px}.evidence-dialog nav button[aria-pressed=true]{background:#345d6d;color:#fff}.evidence-dialog .evidence-boundary{font-size:19px;line-height:1.5;color:#a45836;margin:0!important}.evidence-body{min-height:0;flex:1;overflow:auto;overscroll-behavior:contain}.evidence-body :deep(.experiment-evidence){margin-top:4px}.evidence-body :deep(.finding){font-size:24px}.evidence-body :deep(.boundary){font-size:18px}.evidence-body :deep(.budget-table){margin:12px 0}.evidence-body :deep(svg){height:210px}.evidence-body :deep(.early-layout){margin:12px 0}
</style>
